Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": "fit",
  "background": "transparent",
  "padding": 8,
  "signals": [
    { "name": "gap", "value": 12 },
    { "name": "columns", "update": "max(3, floor(width / 210))" },
    { "name": "cardWidth", "update": "(width - ((columns - 1) * gap)) / columns" },
    { "name": "cardHeight", "value": 90 }
  ],
  "data": [
    { "name": "dataset" },
    {
      "name": "cards",
      "source": "dataset",
      "transform": [
        {
          "type": "collect",
          "sort": { "field": "FIN CB Saldo Atual", "order": "descending" }
        },
        { "type": "window", "ops": ["row_number"], "as": ["index"] },
        {
          "type": "formula",
          "as": "pctValor",
          "expr": "toNumber(replace(replace(replace(datum[''Texto Caixa''], ''Representa do Caixa: '', ''''), ''%'', ''''), '','', ''.''))"
        },
        { "type": "formula", "as": "pct", "expr": "datum.pctValor / 100" },
        { "type": "formula", "as": "col", "expr": "(datum.index - 1) % columns" },
        { "type": "formula", "as": "row", "expr": "floor((datum.index - 1) / columns)" },
        { "type": "formula", "as": "xpos", "expr": "datum.col * (cardWidth + gap)" },
        { "type": "formula", "as": "ypos", "expr": "datum.row * (cardHeight + gap)" }
      ]
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": { "data": "cards" },
      "encode": {
        "update": {
          "x": { "field": "xpos" },
          "y": { "field": "ypos" },
          "width": { "signal": "cardWidth" },
          "height": { "signal": "cardHeight" },
          "fill": { "value": "#ffffff" },
          "stroke": { "value": "#d9d9d9" },
          "strokeWidth": { "value": 1 },
          "cornerRadius": { "value": 8 }
        }
      }
    },
    {
      "type": "rect",
      "from": { "data": "cards" },
      "encode": {
        "update": {
          "x": { "field": "xpos" },
          "y": { "field": "ypos" },
          "width": { "value": 4 },
          "height": { "signal": "cardHeight" },
          "fill": { "value": "#193246" },
          "cornerRadiusTopLeft": { "value": 8 },
          "cornerRadiusBottomLeft": { "value": 8 }
        }
      }
    },
    {
      "type": "text",
      "from": { "data": "cards" },
      "encode": {
        "update": {
          "x": { "signal": "datum.xpos + 18" },
          "y": { "signal": "datum.ypos + 24" },
          "text": { "field": "Banco" },
          "fontSize": { "value": 12 },
          "fontWeight": { "value": "bold" },
          "fill": { "value": "#15283A" },
          "limit": { "signal": "cardWidth - 36" }
        }
      }
    },
    {
      "type": "text",
      "from": { "data": "cards" },
      "encode": {
        "update": {
          "x": { "signal": "datum.xpos + 18" },
          "y": { "signal": "datum.ypos + 55" },
          "text": { "field": "FIN CB Saldo Atual__formatted" },
          "fontSize": { "value": 20 },
          "fontWeight": { "value": "bold" },
          "fill": { "value": "#0070C0" },
          "limit": { "signal": "cardWidth - 36" }
        }
      }
    },
    {
      "type": "text",
      "from": { "data": "cards" },
      "encode": {
        "update": {
          "x": { "signal": "datum.xpos + 18" },
          "y": { "signal": "datum.ypos + 78" },
          "text": { "signal": "format(datum.pct, ''.1%'') + '' do caixa total''" },
          "fontSize": { "value": 10 },
          "fill": { "value": "#6F7A86" }
        }
      }
    }
  ]
}'
